.theme-btn {
  font-size: 17px;
  position: relative;
  z-index: 1;
  overflow: hidden;
  font-weight: 700;
  text-transform: capitalize;
  height: 56px;
  line-height: 56px;
  background-color: var(--theme);
  overflow: hidden;
  display: inline-block;
  padding: 0 32px;
  color: var(--header);
  border-radius: 8px;
  letter-spacing: -2%;
}
@media (max-width: 575px) {
  .theme-btn {
    padding: 0 22px;
    font-size: 15px;
  }
}
.theme-btn i {
  margin-left: 10px;
}
.theme-btn::before {
  content: "";
  position: absolute;
  width: 0;
  top: -10px;
  height: 0;
  background-color: var(--theme2);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  transition: all 0.8s ease;
  z-index: -1;
}
.theme-btn:hover {
  color: var(--white);
  border-color: var(--theme);
}
.theme-btn:hover::before {
  width: 800px;
  height: 800px;
  display: inline-block;
}
.theme-btn.small-btn {
  height: 53px;
  line-height: 53px;
  padding: 0 30px;
}
.theme-btn.theme-bg-2 {
  background-color: var(--theme2);
  color: var(--white);
}
.theme-btn.theme-bg-2::before {
  background-color: var(--theme);
}
.theme-btn.theme-bg-2:hover {
  color: var(--header);
}

